/* ---------- Ticket list ---------- */
/* rows run edge to edge inside the panel, so there is one surface instead of nested ones */
.tkx{padding:12px 0 0;display:flex;flex-direction:column;gap:6px;min-height:340px;overflow:hidden}
.tkx-h{display:flex;align-items:center;justify-content:space-between;padding:0 16px 4px;font-size:14px}
.tkx-h b{font-weight:500}
.tkx-sg button{font-size:12px;height:26px;padding:0 9px}
.tkx-list{display:flex;flex-direction:column}
.tkx-t{transition:background .2s;box-shadow:inset 0 1px 0 var(--line)}
.tkx-t:hover{background:var(--row)}
.tkx-t.open{background:color-mix(in srgb,var(--wash) 50%,var(--surface))}
.tkx-r{display:grid;grid-template-columns:auto 1fr auto;align-items:center;gap:10px;width:100%;padding:10px 16px;text-align:left}
.tkx-r .pr{display:flex;align-items:center;justify-content:center;width:18px;height:18px}
.tkx-r .pr .dot{width:8px;height:8px}
.tkx-r .t{display:flex;flex-direction:column;min-width:0;font-size:13px}
.tkx-r .t b{font-weight:500;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.tkx-r .t span{font-size:12px;color:var(--muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.tkx-r .m{display:flex;align-items:center;gap:6px}
.tkx-r .m .av{width:20px;height:20px;font-size:9px}
.tkx-r .w{font-size:11.5px;color:var(--muted)}
.tkx-d{padding:0 16px 14px 44px;display:flex;flex-direction:column;gap:8px}
.tkx-q{font-size:12.5px;line-height:1.5;color:var(--fg2)}
.tkx-s{padding:10px 12px;border-radius:12px;background:var(--surface);box-shadow:inset 0 0 0 1px var(--line);font-size:12.5px;line-height:1.5;color:var(--fg)}
.tkx-s .lb{display:flex;align-items:center;gap:6px;font-size:11.5px;color:var(--accent-fg,var(--accent));font-weight:500;margin-bottom:4px}
.tkx-s [contenteditable]{outline:0;border-radius:6px}
.tkx-s [contenteditable]:focus{box-shadow:0 0 0 1.5px var(--accent-mark,var(--accent));padding:2px 4px;margin:-2px -4px}
.tkx-a{display:flex;gap:6px;justify-content:flex-end}
.tkx-e{padding:40px 10px;text-align:center;font-size:13px;color:var(--muted)}
.tkx-t.leave{animation:leave .35s var(--ease) both}

DM.def('ticket-list', (r, c) => {
  const T = [
    { p:'var(--bad)', pn:'Urgent', t:'Agent stopped mid export', f:'Northwind', a:['MK','var(--pl)'], w:'4m', q:'The token export stopped at 60% and nothing has happened for 20 minutes.', s:'Sorry about that. The run paused at your $5 spend cap. I have raised it for this run and it finished just now. Your tokens are in the Exports tab.', st:'open' },
    { p:'var(--warn)', pn:'High', t:'Figma frames not syncing', f:'Lumen Labs', a:['JO','var(--pm)'], w:'22m', q:'New frames from this morning are not showing up in DesignMe.', s:'The Figma token for your workspace expired yesterday. Reconnect it from Settings, then the frames will sync within a minute.', st:'open' },
    { p:'var(--accent-mark,var(--accent))', pn:'Normal', t:'How do I share a run?', f:'Orbit', a:['DA','var(--pb)'], w:'1h', q:'Can I send an agent run to someone outside my team?', s:'Yes. Open the run, click Share, and turn on "Anyone with the link". They can view it without an account.', st:'open' },
    { p:'var(--faint)', pn:'Low', t:'Invoice address change', f:'Kite Health', a:['MK','var(--pl)'], w:'2d', q:'', s:'', st:'done' }
  ];
  const list = $('.tkx-list', r); let f = 'open', open = null;
  function paint(anim){
    const L = T.filter(t => t.st === f);
    list.innerHTML = L.length ? L.map(t => `<div class="tkx-t${open === t ? ' open' : ''}"><button class="tkx-r"><span class="pr" data-tip="${t.pn}"><span class="dot" style="color:${t.p}"></span></span><span class="t"><b>${t.t}</b><span>${t.f}${t.q && open !== t ? ' · ' + t.q : ''}</span></span><span class="m"><span class="w">${t.w}</span>${AV(t.a[0], t.a[1])}</span></button>${open === t ? `<div class="tkx-d"><div class="tkx-q">${t.q}</div><div class="tkx-s"><div class="lb">${I('spark','xs')}Suggested reply</div><div class="tx" contenteditable="true" spellcheck="false">${t.s}</div></div><div class="tkx-a"><button class="pill ghost sm ed">${I('edit','xs')}Edit</button><button class="pill accent sm sd">${I('send','xs')}Send and solve</button></div></div>` : ''}</div>`).join('') : '<div class="tkx-e">All caught up</div>';
    if (anim) stagger($$('.tkx-t', list), 40);
    $$('.tkx-t', list).forEach((el, i) => { const t = L[i];
      $('.tkx-r', el).onclick = () => { open = open === t ? null : t; paint(); const d = $('.tkx-d', list); if (d) stagger([...d.children], 50); };
      const sd = $('.sd', el); if (sd) sd.onclick = () => c.run(async () => { sd.innerHTML = '<span class="spin"></span>'; await c.wait(700); t.s = $('.tx', el).textContent; t.st = 'done'; open = null; el.classList.add('leave'); await c.wait(330); paint(); });
      const ed = $('.ed', el); if (ed) ed.onclick = () => { const tx = $('.tx', el); tx.focus({ preventScroll:true }); const s = document.getSelection(); s.selectAllChildren(tx); s.collapseToEnd(); };
    });
  }
  seg($('.tkx-sg', r), v => { f = v; open = null; paint(true); });
  paint(true);
  c.later(1000, () => { if (!open){ open = T[0]; paint(); stagger([...$('.tkx-d', list).children], 50); } });
});
